import json,re
from pathlib import Path
b=Path('/tmp/stationops-delivery-results');rows=[]
for label in ['control','fallback','combined','delivery']:
 for seed in [7,11,23]:
  path=b/f'{label}-{seed}.json'
  if not path.exists():continue
  d=json.loads(path.read_text())
  for batch,r in zip(d['batches'],d['result']['rounds']):
   rows.append(dict(run=path.stem,shift=batch['shift'],seconds=batch['seconds'],coverage=r['belief_metrics']['coverage'],brier=r['belief_metrics']['brier_score'],beliefs=r['beliefs'],score=d['result']['aggregate']['station_score'],regret=d['result']['aggregate']['regret'],aborts=batch['metrics']['search_aborts'],pops=batch['metrics']['agenda_pops']))
  if label=='control':
   old=json.load(open(f'/tmp/stationops-depth-results/control-{seed}.json'))
   norm=lambda x:re.sub(r'kb[0-9a-f]{32}','kbUUID',json.dumps(x))
   assert norm([x['answers'] for x in d['batches']])==norm([x['answers'] for x in old['batches']]), seed
for row in rows:print(row['run'],row['shift'],round(row['seconds'],2),row['coverage'],round(row['brier'],6),row['score'],row['regret'],row['aborts'],row['pops'])
(b/'summary.json').write_text(json.dumps(rows,indent=2)+'\n')
